-- Importa os professores da "LISTA FORCA=LGPD - TRAB" (PDF) que AINDA NÃO existem no sistema.
--
-- Regras:
--   * Só entra quem não tem ID_FUNCIONAL nem matrícula já cadastrados (quem já está lá não é tocado).
--   * Um registro por ID funcional; se aparece em mais de um vínculo/setor, os setores são somados.
--   * SETOR_DESC que corresponde a uma unidade do sistema (por sigla) vira unidade (M2M + principal).
--     "FAETERJ Rio de Janeiro" == Fernando Mota (FMO).
--     Qualquer outro setor (ETE, CETEP, ...) NÃO é unidade: fica em locais_lotacao (texto separado por " | ").
--   * Tipo = EFETIVO / CONCURSADO / TERCEIRIZADO. Regime = 20h, 25h ou 40h.
--     Reaproveita o Tipo de Contrato existente (mesma categoria + horas); se não houver, cria.
--   * Sem matrícula no PDF -> matrícula provisória SEM-MATRICULA-<id>.
--
-- Não usa tabelas temporárias nem de apoio: são 3 comandos independentes (o 3º é um único INSERT
-- com CTEs). Seguro para rodar mais de uma vez. Faça backup antes. Rode tudo de uma vez no SQL Editor.

-- 1) coluna dos locais que não são unidade
ALTER TABLE harpiadb_professores_professor
    ADD COLUMN IF NOT EXISTS locais_lotacao TEXT NOT NULL DEFAULT '';

-- 2) tipos de contrato necessários (reaproveita o existente ou cria)
DO $$
DECLARE r record; v_exist bigint; v_dias int; v_cls int; v_nome text;
BEGIN
    FOR r IN SELECT * FROM (VALUES ('CONCURSADO',20),('CONCURSADO',25),('CONCURSADO',40),('EFETIVO',20),('EFETIVO',40),('TERCEIRIZADO',20),('TERCEIRIZADO',40)) AS c(categoria, horas) LOOP
        SELECT id INTO v_exist FROM harpiadb_professores_tipo_contrato
        WHERE categoria = r.categoria AND regime_trabalho ILIKE r.horas || 'h%'
        ORDER BY id LIMIT 1;
        IF v_exist IS NULL THEN
            v_dias := CASE WHEN r.horas >= 40 THEN 3 ELSE 2 END;
            v_cls  := CASE WHEN r.horas >= 40 THEN 6 WHEN r.horas >= 25 THEN 5 ELSE 4 END;
            v_nome := CASE r.categoria WHEN 'EFETIVO' THEN 'Professor Efetivo '
                                       WHEN 'CONCURSADO' THEN 'Professor Concursado '
                                       ELSE 'Professor Terceirizado ' END || r.horas || 'h';
            INSERT INTO harpiadb_professores_tipo_contrato
                (nome, categoria, regime_trabalho, dias_presenca_obrigatorios, max_class_hours, max_total_hours, max_classes)
            VALUES (v_nome, r.categoria, r.horas || 'h', v_dias, r.horas / 2, r.horas, v_cls);
        END IF;
    END LOOP;
END $$;

