setor_unidade(setor, sigla) AS (
VALUES
 ('FAETERJ Barra Mansa','BRM'),('FAETERJ Bom Jesus de Itabapoana','BJI'),('FAETERJ Campos dos Goytcazes','CGO'),
 ('FAETERJ Duque de Caxias','DCX'),('FAETERJ Itaperuna','ITA'),('FAETERJ Paracambi','PRC'),
 ('FAETERJ Petrópolis','PTR'),('FAETERJ Rio de Janeiro','FMO'),('FAETERJ Santo Antônio de Pádua','SAP'),
 ('FAETERJ Três Rios','TRS'),('FAETERJ Volta Redonda','VRD'),('ISEPAM','ISEPAM'),
 ('ISEPAM - Instituto Superior','ISEPAM'),('ISERJ - Instituto Superior','ISERJ'),
 ('ISERJ - Instituto Superior de Educação','ISERJ')
),
prof_unid AS (
    SELECT s.id_funcional, u.id AS unidade_id, min(t.pos) AS ordem
    FROM stg s
    CROSS JOIN LATERAL unnest(string_to_array(s.setores_unid, '|')) WITH ORDINALITY AS t(setor, pos)
    JOIN setor_unidade m ON m.setor = t.setor
    JOIN harpiadb_nucleo_unidade u ON upper(u.sigla) = upper(m.sigla)
    WHERE s.setores_unid <> ''
    GROUP BY s.id_funcional, u.id
),
novos AS (
    SELECT s.* FROM stg s
    WHERE NOT EXISTS (SELECT 1 FROM harpiadb_professores_professor p
                      WHERE p."ID_FUNCIONAL" = s.id_funcional OR p.rh_matricula = s.matricula)
),
ins AS (
    INSERT INTO harpiadb_professores_professor
        ("ID_FUNCIONAL", rh_matricula, rh_nome, tipo_contrato_id, unidade_principal_id,
         locais_lotacao, is_cedido, ha, status)
    SELECT n.id_funcional, n.matricula, n.nome,
           (SELECT t.id FROM harpiadb_professores_tipo_contrato t
             WHERE t.categoria = n.categoria AND t.regime_trabalho ILIKE n.horas || 'h%'
             ORDER BY t.id LIMIT 1),
           (SELECT pu.unidade_id FROM prof_unid pu WHERE pu.id_funcional = n.id_funcional
             ORDER BY pu.ordem LIMIT 1),
           n.locais, false, 0, 'Ativo'
    FROM novos n
    RETURNING id, "ID_FUNCIONAL" AS id_funcional
)
INSERT INTO harpiadb_professores_professor_unidades (professor_id, unidade_id)
SELECT i.id, pu.unidade_id
FROM ins i
JOIN prof_unid pu ON pu.id_funcional = i.id_funcional;

